# Display shipping options
import json

s = data.get('shipping_options', {})
s_err = data.get('shipping_options_error', None)
print("SHIPPING OPTIONS:")
if s_err:
    print(f"  Error: {s_err}")
elif s:
    opts = s.get('options', s if isinstance(s, list) else [])
    if isinstance(s, dict) and 'options' not in s:
        print(f"  Raw: {json.dumps(s, indent=2)[:1500]}")
    else:
        for opt in opts:
            name = opt.get('name', opt.get('method', '?'))
            cost = opt.get('cost', opt.get('price', '?'))
            eta = opt.get('estimated_days', opt.get('eta', opt.get('delivery_days', '?')))
            print(f"  - {name}: ${cost}, Est. {eta} days")
else:
    print("  No shipping options returned")

# Display shipping policy
import json

p = data.get('shipping_policy', {})
p_err = data.get('shipping_policy_error', None)
print("SHIPPING POLICY:")
if p_err:
    print(f"  Error: {p_err}")
elif p:
    summary = p.get('summary', '')
    rules = p.get('rules', [])
    print(f"  Summary: {summary}")
    if rules:
        print("  Rules:")
        for r in rules:
            if isinstance(r, str):
                print(f"    - {r}")
            elif isinstance(r, dict):
                print(f"    - {json.dumps(r)}")
    if not summary and not rules:
        print(f"  Raw: {json.dumps(p, indent=2)[:2000]}")
else:
    print("  No shipping policy returned")

# Also show the products to understand CI-0006
import json

prods = data.get('products', [])
ci6_prod = None
for p in prods:
    pid = p.get('product_id', '')
    if pid == 'CI-0006':
        ci6_prod = p
        break

print("PRODUCT CI-0006 DETAILS:")
if ci6_prod:
    for k, v in ci6_prod.items():
        if k == 'variants_json' and v:
            parsed = json.loads(v) if isinstance(v, str) else v
            print(f"  {k}: {json.dumps(parsed, indent=2)[:1000]}")
        elif k == 'specs_json' and v:
            parsed = json.loads(v) if isinstance(v, str) else v
            print(f"  {k}: {json.dumps(parsed, indent=2)[:500]}")
        else:
            val_str = str(v)
            if len(val_str) > 200:
                val_str = val_str[:200] + "..."
            print(f"  {k}: {val_str}")
else:
    print("  CI-0006 not found in products. Available product IDs:")
    for p in prods[:10]:
        print(f"    {p.get('product_id')}: {p.get('name')}")

